import test;

fn kind(s: string, i: int): int {
    mut r: int;
    match s[i] {
        matches 'a': r = 1; done
        matches 'b': r = 2; done
        matches _ if s[i] >= '0': r = 3; done
        matches _: r = 0; done
    }
    return r;
}

