    mut lo: int = 0;
    mut hi: int = arr.length() - 1;
    while lo < hi {
        immut tmp: int = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = tmp;
        lo++;
        hi--;
    }
}

